python
def selectionProofProofStrip(readings):
    a=readings
    out=[]
    sums=set()
    def visit(i,s):
        if i==len(a):
            sums.add(s)
            return
        visit(i+1,s)
        visit(i+1,s+a[i])
    visit(0,0)
    out=sorted(sums)
    return out


java
class Solution {
  public int[] selectionProofProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>sums=new TreeSet<>();class Walk {void visit(int i,int s){if(i==a.length){sums.add(s);return;}visit(i+1,s);visit(i+1,s+a[i]);}}new Walk().visit(0,0);out.addAll(sums);}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
